using System.Security.Cryptography;
using System.Text;
using UnscRelay.Core;
static class NativeIntegrationChecks
{
    public static async Task<int> Run(string tools, string helper, int port = 0)
    {
        tools = Path.GetFullPath(tools); helper = Path.GetFullPath(helper); var root = Path.Combine(Path.GetTempPath(), "relay-native-integration-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(root); int checks = 0; void Check(bool value, string name) { if (!value) throw new Exception(name); Console.WriteLine("PASS " + name); checks++; }
        var bin = Path.Combine(tools, "Cygwin", "bin"); var keygen = Path.Combine(bin, "ssh-keygen.exe"); try
        {
            var path = Path.Combine(root, "key"); await NativeClient.Capture(keygen, ["-q", "-t", "mldsa44-ed25519", "-N", "native fixture passphrase", "-f", NativeClient.CygwinPath(path)]); var bytes = File.ReadAllBytes(path); var asks = 0;
            await using var bridge = new NativeBridge(req => { asks++; return Task.FromResult(new NativeReply(true, "native fixture passphrase")); }); var pub = await NativeAgent.ImportIdentity(bin, bytes, bridge, helper); Check(asks > 0 && pub.StartsWith("ssh-mldsa44-ed25519 "), "Encrypted hybrid key loaded through authenticated helper and stdin");
            using var vault = new KeyVault(Path.Combine(root, "vault")); vault.Unlock("Native archive fixture password"); var key = vault.ImportNative("Hybrid fixture", bytes, pub); Check(vault.List().Single().Kind == "ssh-native-key" && key.PublicKey == pub, "Native identity is listed in shared vault"); Check(vault.Read(key.Id).SequenceEqual(bytes), "Private bytes remain unchanged in vault"); Check(!File.ReadAllText(Path.Combine(root, "vault")).Contains("Hybrid fixture"), "Native metadata is encrypted at rest"); vault.UpdateMetadata(key.Id, "Renamed native", "fixture comment"); vault.Lock(); vault.Unlock("Native archive fixture password"); Check(vault.List().Single().Name == "Renamed native" && vault.List().Single().Fingerprint == key.Fingerprint, "Native identity rename and ID survive reopening");
            var hostStore = new HostKeyStore(Path.Combine(root, "hosts.json")); var request = new NativeRequest("", "host", ["HOSTNAME", "fixture.invalid", "22", "fixture.invalid", key.Algorithm, key.PublicKey.Split(' ')[1]]); var prompts = 0; var line = NativeIdentity.KnownHost(request, hostStore, _ => { prompts++; return true; }); Check(prompts == 1 && line.Contains(pub), "First host requires explicit shared trust"); NativeIdentity.KnownHost(request, hostStore, _ => throw new Exception("Repeated prompt")); Check(hostStore.List().Count == 1, "Trusted host reused without duplicate entries"); var changed = false; try { NativeIdentity.KnownHost(request with { Arguments = ["HOSTNAME", "fixture.invalid", "22", "fixture.invalid", "ssh-ed25519", "AAAAC3NzaC1lZDI1NTE5AAAAIFLm8BoVvFnkNXdN4O7HDiqZQLVLNqoA3MYvDmhIs00z"] }, hostStore, _ => true); } catch (IOException) { changed = true; }
            Check(changed, "Changed key rejected despite willingness to confirm"); hostStore.Forget("fixture.invalid", 22); Check(hostStore.List().Count == 0, "Forgetting host applies to native path");
            var standard = KeyGeneration.Generate(vault, "Ordinary vault key", "ed25519"); var ordinary = vault.Read(standard.Id); await using var blankBridge = new NativeBridge(_ => Task.FromResult(new NativeReply(true, ""))); try { var ordinaryPub = await NativeAgent.ImportIdentity(bin, ordinary, blankBridge, helper); Check(NativeIdentity.Parse(ordinaryPub).Fingerprint == standard.Fingerprint, "Existing generated Ed25519 interoperates with original OpenSSH"); } finally { CryptographicOperations.ZeroMemory(ordinary); }
            var legacyEncoded = Org.BouncyCastle.Crypto.Utilities.OpenSshPrivateKeyUtilities.EncodePrivateKey(new Org.BouncyCastle.Crypto.Parameters.Ed25519PrivateKeyParameters(new Org.BouncyCastle.Security.SecureRandom()));
            byte[] legacy = []; byte[] converted = []; try { using var writer = new StringWriter(); new Org.BouncyCastle.Utilities.IO.Pem.PemWriter(writer).WriteObject(new Org.BouncyCastle.Utilities.IO.Pem.PemObject("OPENSSH PRIVATE KEY", legacyEncoded)); legacy = Encoding.UTF8.GetBytes(writer.ToString()); converted = NativeAgent.CompatibleIdentity(legacy); var legacyKey = vault.Import("Legacy fixture", legacy); var migratedPub = await NativeAgent.ImportIdentity(bin, converted, blankBridge, helper); Check(NativeIdentity.Parse(migratedPub).Fingerprint == legacyKey.Fingerprint, "Previously generated Ed25519 converted in memory without replacing vault entry"); } finally { CryptographicOperations.ZeroMemory(legacyEncoded); CryptographicOperations.ZeroMemory(legacy); CryptographicOperations.ZeroMemory(converted); }
            if (port > 0) { var trusted = new HostKeyStore(Path.Combine(root, "loopback-hosts.json")); var accepted = 0; await using var connectionBridge = new NativeBridge(req => Task.FromResult(req.Action == "host" ? new NativeReply(true, NativeIdentity.KnownHost(req, trusted, _ => { accepted++; return true; })) : new NativeReply(true, "relay-test-password"))); var config = Path.Combine(root, "config"); await File.WriteAllTextAsync(config, NativePolicy.Configuration(helper, "") + "Host fixture\n HostName 127.0.0.1\n Port " + port + "\n User password-only\n PreferredAuthentications password\n"); await NativeClient.Capture(Path.Combine(bin, "chmod.exe"), ["600", NativeClient.CygwinPath(config)]); var start = new System.Diagnostics.ProcessStartInfo(Path.Combine(bin, "ssh.exe")) { UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true, RedirectStandardInput = true }; foreach (var arg in new[] { "-F", NativeClient.CygwinPath(config), "fixture", "fixture-ok" }) start.ArgumentList.Add(arg); var env = new Dictionary<string, string>(); connectionBridge.Apply(env); foreach (var pair in env) start.Environment[pair.Key] = pair.Value; start.Environment["SSH_ASKPASS"] = NativeClient.CygwinPath(helper); start.Environment["SSH_ASKPASS_REQUIRE"] = "force"; start.Environment["RELAY_ASKPASS_HELPER"] = "1"; start.Environment["DISPLAY"] = "relay"; using var process = System.Diagnostics.Process.Start(start)!; process.StandardInput.Close(); var output = process.StandardOutput.ReadToEndAsync(); var error = process.StandardError.ReadToEndAsync(); await process.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(40)); var stdout = await output; var stderr = await error; Check(process.ExitCode == 0 && stdout.Contains("fixture hook output"), "Real OpenSSH authenticates with app helper and executes on loopback: " + (process.ExitCode == 0 ? "OK" : stderr[..Math.Min(stderr.Length, 500)])); Check(accepted == 1 && trusted.List().Single().PublicKey.Length > 0, "Loopback trust uses shared host manager"); }
            CryptographicOperations.ZeroMemory(bytes); Console.WriteLine(checks + " native integration checks passed"); return 0;
        }
        finally { if (Path.GetFullPath(root).StartsWith(Path.GetFullPath(Path.GetTempPath()), StringComparison.OrdinalIgnoreCase)) Directory.Delete(root, true); }
    }
}
